DROP TABLE IF EXISTS `mes_pro_route_version`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_route_version` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `route_id` bigint NOT NULL COMMENT '路线ID',
  `version_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '版本号',
  `active` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否当前版本',
  `lifecycle_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '生命周期状态：DRAFT/PENDING_APPROVAL/READY_TO_PUBLISH/ACTIVE/SUPERSEDED/REJECTED/CANCELLED',
  `source_route_version_id` bigint DEFAULT NULL COMMENT '来源路线版本ID',
  `route_snapshot_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'åˆ›å»ºæ—¶å†»ç»“è·¯çº¿å¿«ç…§',
  `change_summary_json` json DEFAULT NULL COMMENT '版本变更摘要',
  `validation_result_json` json DEFAULT NULL COMMENT '发布校验结果',
  `submitted_by` bigint DEFAULT NULL COMMENT '提交人',
  `submitted_time` datetime DEFAULT NULL COMMENT '提交时间',
  `approval_process_instance_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批流程实例ID',
  `published_by` bigint DEFAULT NULL COMMENT '发布人',
  `published_time` datetime DEFAULT NULL COMMENT '发布时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `active_unique_flag` tinyint GENERATED ALWAYS AS (if(((`deleted` = 0x00) and (`active` = 0x01)),1,NULL)) STORED COMMENT '当前生效版本唯一约束标记',
  `open_candidate_route_id` bigint GENERATED ALWAYS AS ((case when ((`deleted` = 0x00) and (`active` = 0x00) and (`lifecycle_status` in (_utf8mb4'DRAFT',_utf8mb4'PENDING_APPROVAL',_utf8mb4'READY_TO_PUBLISH'))) then `route_id` else NULL end)) STORED COMMENT '未完成候选版本唯一约束路线标记',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_mes_pro_route_version_no` (`tenant_id`,`route_id`,`version_no`,`deleted`) USING BTREE,
  UNIQUE KEY `uk_mes_pro_route_version_active_one` (`tenant_id`,`route_id`,`active_unique_flag`) USING BTREE,
  UNIQUE KEY `uk_mes_route_version_open_candidate` (`tenant_id`,`open_candidate_route_id`) USING BTREE,
  KEY `idx_mes_pro_route_version_active` (`tenant_id`,`route_id`,`active`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=456 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 工艺路线版本';
/*!40101 SET character_set_client = @saved_cs_client */;

