DROP TABLE IF EXISTS `mes_pro_route_process_flow_edge`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_route_process_flow_edge` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `graph_version` bigint NOT NULL DEFAULT '1' COMMENT '关系图版本',
  `source_route_process_id` bigint NOT NULL COMMENT '前置路线工序ID',
  `target_route_process_id` bigint NOT NULL COMMENT '后置路线工序ID',
  `relation_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NORMAL' COMMENT '关系类型：NORMAL',
  `sort` int DEFAULT NULL COMMENT '同一来源工序的出边排序',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
