--
-- Table structure for table `mes_pro_route_schedule_config`
--

DROP TABLE IF EXISTS `mes_pro_route_schedule_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_route_schedule_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `route_version_id` bigint NOT NULL COMMENT '路线版本ID',
  `item_id` bigint DEFAULT NULL COMMENT '产品物料ID',
  `route_process_id` bigint NOT NULL COMMENT '路线工序ID',
  `capacity_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产能模式',
  `hourly_capacity` decimal(18,6) DEFAULT NULL COMMENT '每小时产能',
  `infinite_duration_quantity_factor` decimal(18,6) DEFAULT NULL COMMENT '无限产能数量系数',
  `infinite_duration_base_minutes` decimal(18,6) DEFAULT NULL COMMENT '无限产能基础分钟',
  `night_shift_enabled` bit(1) DEFAULT b'0' COMMENT '是否启用夜班',
  `calendar_rule_id` bigint DEFAULT NULL COMMENT '日历规则ID',
  `config_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置版本',
  `copied_from_config_id` bigint DEFAULT NULL COMMENT '复制来源配置ID',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_mes_pro_route_schedule_config_item_process` (`tenant_id`,`route_version_id`,`item_id`,`route_process_id`,`deleted`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5837 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 路线排产侧配置';
/*!40101 SET character_set_client = @saved_cs_client */;

