CREATE TABLE `mes_pro_route_flow_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `use_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置类型：SCHEDULE/BATCH',
  `enabled` bit(1) NOT NULL DEFAULT b'0' COMMENT '配置启用状态',
  `config_version` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置版本',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_mes_pro_route_flow_config` (`tenant_id`,`route_id`,`use_type`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=90002956 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 工艺流程配置';
