--
-- Table structure for table `mes_pro_route_flow_process_config`
--

DROP TABLE IF EXISTS `mes_pro_route_flow_process_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_route_flow_process_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `route_flow_config_id` bigint NOT NULL COMMENT '工艺流程配置ID',
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `route_process_id` bigint NOT NULL COMMENT '工艺路线工序ID',
  `use_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置类型：SCHEDULE/BATCH',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '当前配置下是否启用',
  `execution_mode` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SEQUENTIAL' COMMENT '批记录执行模式：SEQUENTIAL/PARALLEL',
  `production_quantity_factor` decimal(18,6) NOT NULL DEFAULT '1.000000' COMMENT '生产数量系数，工序计划数量=成品数量*生产数量系数',
  `batch_record_report_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '历史字段：批记录报表ID迁移来源',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_mes_pro_route_flow_process_config` (`tenant_id`,`route_process_id`,`use_type`,`deleted`),
  KEY `idx_mes_pro_route_flow_process_config_flow` (`tenant_id`,`route_flow_config_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=9000257199 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 工艺流程工序配置';
/*!40101 SET character_set_client = @saved_cs_client */;

